-- Applied to STELLAR staging 2026-10-25. 148 extended KB candidates are NOT caller-approved.
CREATE TABLE IF NOT EXISTS public.ai4cc_specialist_kb_candidates (
 stable_id text PRIMARY KEY CHECK(stable_id ~ '^(SAL|SUP)-[0-9]{3}$'),
 package_version text NOT NULL,source_revision text NOT NULL,
 group_name text NOT NULL CHECK(group_name IN ('sales','support')),
 tenant_id uuid NOT NULL,label text NOT NULL,source_authority text NOT NULL,
 candidate_record jsonb NOT NULL,review_state text NOT NULL DEFAULT 'draft'
 CHECK(review_state IN ('draft','review','approved','rejected')),
 caller_approved boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT false,
 created_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT specialist_candidate_no_unapproved_enable CHECK(NOT enabled OR(caller_approved AND review_state='approved')),
 CONSTRAINT specialist_candidate_tenant_binding CHECK(
 (group_name='sales' AND tenant_id='5885a020-d363-4c27-910a-c035eda132f5'::uuid)
 OR (group_name='support' AND tenant_id='d7e80001-0000-4000-b000-000000000001'::uuid))
);
ALTER TABLE public.ai4cc_specialist_kb_candidates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ai4cc_specialist_kb_candidates FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.ai4cc_specialist_kb_candidates TO service_role;
